/// Every negative `VkResult` as a Zig error. Commands return these instead
/// of a raw `Result`; commands that can also return status codes
/// (e.g. `.suboptimal_khr`) return `Error!Result`.
pub const Error = error{
    OutOfHostMemory,
    OutOfDeviceMemory,
    InitializationFailed,
    DeviceLost,
    MemoryMapFailed,
    LayerNotPresent,
    ExtensionNotPresent,
    FeatureNotPresent,
    IncompatibleDriver,
    TooManyObjects,
    FormatNotSupported,
    FragmentedPool,
    Unknown,
    ValidationFailed,
    OutOfPoolMemory,
    InvalidExternalHandle,
    InvalidOpaqueCaptureAddress,
    Fragmentation,
    NotPermitted,
    SurfaceLostKHR,
    NativeWindowInUseKHR,
    OutOfDateKHR,
    IncompatibleDisplayKHR,
    InvalidShaderNV,
    ImageUsageNotSupportedKHR,
    VideoPictureLayoutNotSupportedKHR,
    VideoProfileOperationNotSupportedKHR,
    VideoProfileFormatNotSupportedKHR,
    VideoProfileCodecNotSupportedKHR,
    VideoStdVersionNotSupportedKHR,
    InvalidDrmFormatModifierPlaneLayoutEXT,
    PresentTimingQueueFullEXT,
    FullScreenExclusiveModeLostEXT,
    InvalidVideoStdParametersKHR,
    CompressionExhaustedEXT,
    NotEnoughSpaceKHR,
};

fn resultToError(result: Result) Error {
    return switch (result) {
        .error_out_of_host_memory => error.OutOfHostMemory,
        .error_out_of_device_memory => error.OutOfDeviceMemory,
        .error_initialization_failed => error.InitializationFailed,
        .error_device_lost => error.DeviceLost,
        .error_memory_map_failed => error.MemoryMapFailed,
        .error_layer_not_present => error.LayerNotPresent,
        .error_extension_not_present => error.ExtensionNotPresent,
        .error_feature_not_present => error.FeatureNotPresent,
        .error_incompatible_driver => error.IncompatibleDriver,
        .error_too_many_objects => error.TooManyObjects,
        .error_format_not_supported => error.FormatNotSupported,
        .error_fragmented_pool => error.FragmentedPool,
        .error_unknown => error.Unknown,
        .error_validation_failed => error.ValidationFailed,
        .error_out_of_pool_memory => error.OutOfPoolMemory,
        .error_invalid_external_handle => error.InvalidExternalHandle,
        .error_invalid_opaque_capture_address => error.InvalidOpaqueCaptureAddress,
        .error_fragmentation => error.Fragmentation,
        .error_not_permitted => error.NotPermitted,
        .error_surface_lost_khr => error.SurfaceLostKHR,
        .error_native_window_in_use_khr => error.NativeWindowInUseKHR,
        .error_out_of_date_khr => error.OutOfDateKHR,
        .error_incompatible_display_khr => error.IncompatibleDisplayKHR,
        .error_invalid_shader_nv => error.InvalidShaderNV,
        .error_image_usage_not_supported_khr => error.ImageUsageNotSupportedKHR,
        .error_video_picture_layout_not_supported_khr => error.VideoPictureLayoutNotSupportedKHR,
        .error_video_profile_operation_not_supported_khr => error.VideoProfileOperationNotSupportedKHR,
        .error_video_profile_format_not_supported_khr => error.VideoProfileFormatNotSupportedKHR,
        .error_video_profile_codec_not_supported_khr => error.VideoProfileCodecNotSupportedKHR,
        .error_video_std_version_not_supported_khr => error.VideoStdVersionNotSupportedKHR,
        .error_invalid_drm_format_modifier_plane_layout_ext => error.InvalidDrmFormatModifierPlaneLayoutEXT,
        .error_present_timing_queue_full_ext => error.PresentTimingQueueFullEXT,
        .error_full_screen_exclusive_mode_lost_ext => error.FullScreenExclusiveModeLostEXT,
        .error_invalid_video_std_parameters_khr => error.InvalidVideoStdParametersKHR,
        .error_compression_exhausted_ext => error.CompressionExhaustedEXT,
        .error_not_enough_space_khr => error.NotEnoughSpaceKHR,
        else => error.Unknown,
    };
}

/// The `Result` for an `Error`, e.g. when returning from a layer or callback.
pub fn errorToResult(err: Error) Result {
    return switch (err) {
        error.OutOfHostMemory => .error_out_of_host_memory,
        error.OutOfDeviceMemory => .error_out_of_device_memory,
        error.InitializationFailed => .error_initialization_failed,
        error.DeviceLost => .error_device_lost,
        error.MemoryMapFailed => .error_memory_map_failed,
        error.LayerNotPresent => .error_layer_not_present,
        error.ExtensionNotPresent => .error_extension_not_present,
        error.FeatureNotPresent => .error_feature_not_present,
        error.IncompatibleDriver => .error_incompatible_driver,
        error.TooManyObjects => .error_too_many_objects,
        error.FormatNotSupported => .error_format_not_supported,
        error.FragmentedPool => .error_fragmented_pool,
        error.Unknown => .error_unknown,
        error.ValidationFailed => .error_validation_failed,
        error.OutOfPoolMemory => .error_out_of_pool_memory,
        error.InvalidExternalHandle => .error_invalid_external_handle,
        error.InvalidOpaqueCaptureAddress => .error_invalid_opaque_capture_address,
        error.Fragmentation => .error_fragmentation,
        error.NotPermitted => .error_not_permitted,
        error.SurfaceLostKHR => .error_surface_lost_khr,
        error.NativeWindowInUseKHR => .error_native_window_in_use_khr,
        error.OutOfDateKHR => .error_out_of_date_khr,
        error.IncompatibleDisplayKHR => .error_incompatible_display_khr,
        error.InvalidShaderNV => .error_invalid_shader_nv,
        error.ImageUsageNotSupportedKHR => .error_image_usage_not_supported_khr,
        error.VideoPictureLayoutNotSupportedKHR => .error_video_picture_layout_not_supported_khr,
        error.VideoProfileOperationNotSupportedKHR => .error_video_profile_operation_not_supported_khr,
        error.VideoProfileFormatNotSupportedKHR => .error_video_profile_format_not_supported_khr,
        error.VideoProfileCodecNotSupportedKHR => .error_video_profile_codec_not_supported_khr,
        error.VideoStdVersionNotSupportedKHR => .error_video_std_version_not_supported_khr,
        error.InvalidDrmFormatModifierPlaneLayoutEXT => .error_invalid_drm_format_modifier_plane_layout_ext,
        error.PresentTimingQueueFullEXT => .error_present_timing_queue_full_ext,
        error.FullScreenExclusiveModeLostEXT => .error_full_screen_exclusive_mode_lost_ext,
        error.InvalidVideoStdParametersKHR => .error_invalid_video_std_parameters_khr,
        error.CompressionExhaustedEXT => .error_compression_exhausted_ext,
        error.NotEnoughSpaceKHR => .error_not_enough_space_khr,
    };
}

